checker.setup:
class _Response:
    def __init__(self, status_code, payload):
        self.status_code = status_code
        self._payload = payload

    def json(self):
        return self._payload

tests.code:
calls = []
def fake_get(url, timeout):
    calls.append((url, timeout))
    return _Response(200, {"respondents": "812"})
assert wave_count("W14", fake_get) == 812
assert calls == [("https://survey.example/api/waves/W14", 30)], calls

try:
    wave_count("W14", lambda url, timeout: _Response(503, {}))
except RuntimeError as err:
    assert "503" in str(err), str(err)
else:
    raise AssertionError("no RuntimeError for status 503")
